  $j$[{"seat": "W1", "source": "Wall 11960; fairjudge/w1/g635/grade_plan635.md (commit 28082b0c)", "verdict": "PASS WITH N1 to N3 (plan rev 0)", "wall_id": 11960, "md5_graded": "803c9032", "verdict_norm": "PASS"}]$j$::jsonb,
